-- Canary for the QAdmissions SQL scoring path (qadmissions_predict).
--
-- Scores 36 synthetic rows through the registered model and returns any row
-- whose result differs from the result the qadmission_review scoring code
-- gives: a different ok flag, a score more than 1e-05 apart, or different
-- error text. Each row changes one input from a baseline, so a wrongly mapped
-- input, another model version or a change to the inputs on either side
-- fails the test. All values are made up.
--
-- Generated by qadmission_review/python_pipeline_snowflake/generate_canary_test.py.
-- Regenerate it rather than editing the values by hand.

with canary (
    case_id, description, sex, age, alcohol_cat6, b_af, b_ccf, b_anticoagulant, b_antidepressant, b_antipsychotic, b_anycancer, b_asthmacopd, b_corticosteroids, b_cvd, b_epilepsy, b_falls, b_liverpancreas, b_malabsorption, b_manicschiz, b_nsaid, b_renal, b_type1, b_type2, b_vte, bmi, c_hb, ethrisk, hes_admitprior_cat, high_lft, high_platelet, sha1, smoke_cat, surv, town, expected_ok, expected_score_percent, expected_errors
) as (
    select * from values
        (1, 'baseline (example input)', 'female', 80, 0, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 23.0, FALSE, 1, 0, FALSE, FALSE, 3, 0, 1, 0.0, TRUE, 7.734115569922196, NULL),
