scored as (
    select
        case_id,
        description,
        expected_ok,
        expected_score_percent::float as expected_score_percent,
        expected_errors,
        {{ qadmissions_predict('c') }} as prediction
    from canary c
),

compared as (
    select
        case_id,
        description,
        expected_ok,
        prediction:"ok"::boolean as actual_ok,
        expected_score_percent,
        prediction:"score_percent"::float as actual_score_percent,
        expected_errors,
        prediction:"errors"::varchar as actual_errors
    from scored
)

select *
from compared
where actual_ok is distinct from expected_ok
   or (actual_score_percent is null) <> (expected_score_percent is null)
   or abs(actual_score_percent - expected_score_percent) > 1e-05
   or coalesce(actual_errors, '') <> coalesce(expected_errors, '')
